let _markdown = "\n\n<Callout type=\"warning\" title=\"Before Reading\">\n  * Only OpenAPI 3.0 and 3.1 are supported.\n  * It only works under RSC\n    environments.\n</Callout>\n\nManual Setup [#manual-setup]\n\n<FeedbackBlock id=\"7e0655cba6e923a6\" body=\"Install the required packages.\">\n  Install the required packages.\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"npm\" groupId=\"package-manager\" persist>\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"npm\">\n      npm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"pnpm\">\n      pnpm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"yarn\">\n      yarn\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"bun\">\n      bun\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"npm\">\n    ```bash\n    npm i fumadocs-openapi shiki\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"pnpm\">\n    ```bash\n    pnpm add fumadocs-openapi shiki\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"yarn\">\n    ```bash\n    yarn add fumadocs-openapi shiki\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"bun\">\n    ```bash\n    bun add fumadocs-openapi shiki\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n<Callout title=\"For Bun PM\" type=\"warning\">\n  If you encountered any issues, please check\n  [#2223](https://github.com/fuma-nama/fumadocs/issues/2223).\n</Callout>\n\nGenerate Styles [#generate-styles]\n\n<FeedbackBlock id=\"3837ef9bb2b59006\" body=\"Add the following line:\">\n  Add the following line:\n</FeedbackBlock>\n\n```css title=\"Tailwind CSS\"\n@import 'tailwindcss';\n@import 'fumadocs-ui/css/neutral.css';\n@import 'fumadocs-ui/css/preset.css';\n/* [!code ++] */\n@import 'fumadocs-openapi/css/preset.css';\n```\n\nConfigure Plugin [#configure-plugin]\n\n<FeedbackBlock id=\"4dd9ddfe4fcca6a4\" body=\"Create an OpenAPI instance on the server.\">\n  Create an OpenAPI instance on the server.\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"lib/openapi.ts\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"lib/openapi.ts\">\n      lib/openapi.ts\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"lib/source.ts\">\n      lib/source.ts\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"lib/openapi.ts\">\n    ```ts\n    import { createOpenAPI } from 'fumadocs-openapi/server';\n\n    export const openapi = createOpenAPI({\n      // the OpenAPI schema, you can also give it an external URL.\n      input: ['./unkey.json'],\n    });\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"lib/source.ts\">\n    ```ts\n    import { openapiPlugin } from 'fumadocs-openapi/server';\n    import { loader } from 'fumadocs-core/source';\n\n    export const source = loader({\n      // [!code ++] optional: adds a badge to each page item in page tree\n      plugins: [openapiPlugin()],\n    });\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n<FeedbackBlock id=\"7a2fff2afa5050c7\" body=\"Create a APIPage component:\">\n  Create a `APIPage` component:\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"components/api-page.tsx\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"components/api-page.tsx\">\n      components/api-page.tsx\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"components/api-page.client.tsx\">\n      components/api-page.client.tsx\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"components/api-page.tsx\">\n    ```tsx\n    import { openapi } from '@/lib/openapi';\n    import { createAPIPage } from 'fumadocs-openapi/ui';\n    import client from './api-page.client';\n\n    export const APIPage = createAPIPage(openapi, {\n      client,\n    });\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"components/api-page.client.tsx\">\n    ```tsx\n    'use client';\n    import { defineClientConfig } from 'fumadocs-openapi/ui/client';\n\n    export default defineClientConfig({\n      // client-side config\n    });\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\nGenerate Pages [#generate-pages]\n\n<Tabs items={[\"MDX Files\", \"Virtual Files\"]}>\n  <Tab>\n    You can generate MDX files directly from your OpenAPI schema.\n\n    Create a script:\n\n    ```js title=\"scripts/generate-docs.ts\"\n    import { generateFiles } from 'fumadocs-openapi';\n    import { openapi } from '@/lib/openapi';\n\n    void generateFiles({\n      input: openapi,\n      output: './content/docs',\n      // we recommend to enable it\n      // make sure your endpoint description doesn't break MDX syntax.\n      includeDescription: true,\n    });\n    ```\n\n    Generate docs with the script:\n\n    ```bash\n    bun ./scripts/generate-docs.ts\n    ```\n\n    Add the `APIPage` component to your MDX Components.\n\n    ```tsx title=\"mdx-components.tsx\"\n    import defaultComponents from 'fumadocs-ui/mdx';\n    import { APIPage } from '@/components/api-page';\n    import type { MDXComponents } from 'mdx/types';\n\n    // make sure you can use it in MDX files\n    export function getMDXComponents(components?: MDXComponents): MDXComponents {\n      return {\n        ...defaultComponents,\n        APIPage,\n        ...components,\n      };\n    }\n    ```\n  </Tab>\n\n  <Tab>\n    You can also use it without generating real files by integrating into [Loader API](/docs/headless/source-api/source).\n\n    ```ts title=\"lib/source.ts\"\n    import { loader, multiple } from 'fumadocs-core/source';\n    import { openapiPlugin, openapiSource } from 'fumadocs-openapi/server';\n    import { docs } from 'fumadocs-mdx:collections/server';\n    import { openapi } from '@/lib/openapi';\n\n    export const source = loader(\n      // [!code ++:6]\n      multiple({\n        docs: docs.toFumadocsSource(),\n        openapi: await openapiSource(openapi, {\n          baseDir: 'openapi',\n        }),\n      }),\n      {\n        baseUrl: '/docs',\n        plugins: [openapiPlugin()],\n        // ...\n      },\n    );\n    ```\n\n    `openapiSource()` is a server-side API that generates pages directly to your `loader()`, hence allowing dynamic generation (e.g. different page tree as schema changes).\n\n    It shares a different type from your original source, explicit handling of OpenAPI pages might be necessary (e.g. in your page component).\n\n    ```tsx title=\"docs/[[...slug]]/page.tsx\"\n    import { APIPage } from '@/components/api-page';\n\n    function Page() {\n      const page = source.getPage('...');\n\n      // for OpenAPI pages\n      if (page.data.type === 'openapi') {\n        return (\n          <DocsPage full>\n            <h1 className=\"text-[1.75em] font-semibold\">{page.data.title}</h1>\n            <DocsBody>\n              <APIPage {...page.data.getAPIPageProps()} />\n            </DocsBody>\n          </DocsPage>\n        );\n      }\n\n      // your original flow below...\n    }\n    ```\n\n    Or where you return text for LLM:\n\n    ```ts\n    import { source } from '@/lib/source';\n    import type { InferPageType } from 'fumadocs-core/source';\n\n    export async function getLLMText(page: InferPageType<typeof source>) {\n      // [!code ++:4]\n      if (page.data.type === 'openapi') {\n        // e.g. return the stringified OpenAPI schema\n        return JSON.stringify(page.data.getSchema().bundled, null, 2);\n      }\n\n      // your original flow below...\n    }\n    ```\n  </Tab>\n</Tabs>\n\nFeatures [#features]\n\n<FeedbackBlock id=\"5a126c0494ef8013\" body=\"The official OpenAPI integration supports:\">\n  The official OpenAPI integration supports:\n</FeedbackBlock>\n\n<FeedbackBlock id=\"4eddf6b7fb177cf7\" body=\"Basic API endpoint informationInteractive API playgroundExample code to send request (in different programming languages)Response samples and TypeScript definitionsRequest parameters and body generated from schemas\">\n  * Basic API endpoint information\n  * Interactive API playground\n  * Example code to send request (in different programming languages)\n  * Response samples and TypeScript definitions\n  * Request parameters and body generated from schemas\n</FeedbackBlock>\n\nDemo [#demo]\n\n<FeedbackBlock id=\"73e8f37cd314f355\" body=\"View demo.\">\n  [View demo](/docs/openapi).\n</FeedbackBlock>\n";
